// Package store holds the typed queries generated by sqlc from
// queries/*.sql over the schema in migrations/. Everything except this file
// is generated: change the SQL and run scripts/generate.sh.
//
// queries/maintenance.sql: the scheduled cleanup (internal/maintenance). Its
// rules are the manual script's (apps/web/src/server/session/maintenance.ts,
// docs/architecture/sessions.md "Operations"), plus expired idempotency keys
// and weather cache rows. Times are compared with the database clock
// atlas_now() (UTC), as the session protocol does.
package store
